contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;
        uint callerBalBefore = address(this).balance;

        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;
        uint callerBalAfter = address(this).balance;

        assert(
            reverted
                ? (depositsAfter == depositsBefore && cBalAfter == cBalBefore && callerBalAfter == callerBalBefore)
                : (depositsAfter == depositsBefore && cBalBefore == cBalAfter + _value && callerBalAfter == callerBalBefore + _value)
        );
    }

    receive() external payable {}
}

