// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 _value) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        uint callerBalBefore = address(this).balance;
        bool reverted;
        try c.withdraw(_value) { reverted = false; } catch { reverted = true; }
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        uint cBalAfter = address(c).balance;
        uint callerBalAfter = address(this).balance;
        assertTrue(reverted
                ? (depositsAfter == depositsBefore && cBalAfter == cBalBefore && callerBalAfter == callerBalBefore)
                : (depositsAfter == depositsBefore && cBalBefore == cBalAfter + _value && callerBalAfter == callerBalBefore + _value));
    }

    function testFuzz_run(uint256 _value) public {
        _run(_value);
    }

    receive() external payable {}
}
